// Secure Express application with proper environment variable usage
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Configuration from environment variables with defaults
const config = {
  port: parseInt(process.env.PORT) || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  allowedOrigins: process.env.ALLOWED_ORIGINS ? 
    process.env.ALLOWED_ORIGINS.split(',') : 
    ['http://localhost:3000', 'http://localhost:5173'],
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  jwtSecret: process.env.JWT_SECRET || 'development-secret-change-in-production',
  databaseUrl: process.env.DATABASE_URL,
  apiTimeout: parseInt(process.env.API_TIMEOUT_MS) || 10000
};

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET'];
if (config.nodeEnv === 'production') {
  requiredEnvVars.push('DATABASE_URL');
}

const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);
if (missingEnvVars.length > 0) {
  console.error('Missing required environment variables:', missingEnvVars.join(', '));
  if (config.nodeEnv === 'production') {
    process.exit(1);
  }
}

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

app.use(cors({
  origin: config.allowedOrigins,
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: config.rateLimitWindowMs,
  max: config.rateLimitMax,
  message: {
    error: 'Too many requests, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request timeout middleware
app.use((req, res, next) => {
  req.setTimeout(config.apiTimeout, () => {
    res.status(408).json({ error: 'Request timeout' });
  });
  next();
});

// Simple authentication middleware
const requireAuth = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.substring(7);

  // In production, validate JWT token using config.jwtSecret
  // This is a simplified example - use a proper JWT library
  if (token !== 'valid-token-placeholder') { // Replace with actual JWT validation
    return res.status(401).json({ error: 'Invalid token' });
  }

  next();
};

// Health endpoint (public)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv,
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Configuration endpoint (protected)
app.get('/config', requireAuth, (req, res) => {
  // Return non-sensitive configuration
  res.json({
    environment: config.nodeEnv,
    rateLimit: {
      windowMs: config.rateLimitWindowMs,
      max: config.rateLimitMax
    },
    apiTimeout: config.apiTimeout
  });
});

// Protected user endpoint
app.get('/users', requireAuth, (req, res) => {
  // In production, this would fetch from database using config.databaseUrl
  // For demo purposes, using mock data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Mask sensitive data before returning
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    email: user.email.replace(/(?<=.).(?=.*@)/g, '*')
  }));

  res.json(sanitizedUsers);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(`${new Date().toISOString()} - Error:`, {
    message: err.message,
    stack: config.nodeEnv === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method
  });

  res.status(500).json({ 
    error: 'Internal server error',
    ...(config.nodeEnv === 'development' && { details: err.message })
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.originalUrl
  });
});

app.listen(config.port, () => {
  console.log(`${new Date().toISOString()} - Server running on port ${config.port} in ${config.nodeEnv} mode`);

  if (config.nodeEnv === 'development') {
    console.log('Development mode warnings:');
    if (config.jwtSecret === 'development-secret-change-in-production') {
      console.warn('  ⚠️  Using default JWT secret - change JWT_SECRET in production');
    }
    if (!config.databaseUrl) {
      console.warn('  ⚠️  DATABASE_URL not set - using mock data');
    }
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

module.exports = app;

