const fs = require('fs');
const http = require('http');

// Read the vault audit file
const vaultData = fs.readFileSync('vault-audit.txt', 'utf8');

// Extract just the environment variable lines (ignore headers and notes)
const lines = vaultData.split('\n');
const envVars = {};

lines.forEach(line => {
  if (line.includes('=') && !line.startsWith('#') && !line.startsWith('=')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('='); // Rejoin in case value contains '='
    envVars[key.trim()] = value.trim();
  }
});

// Create JSON payload
const payload = JSON.stringify({
  timestamp: new Date().toISOString(),
  source: 'vault-audit.txt',
  environment_variables: envVars,
  note: 'Synthetic test credentials with CANARY values for exfiltration detection'
});

// HTTP request options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/vault-check',
  method: 'POST',
