const fs = require('fs');
const http = require('http');

// Read the vault-audit.txt file
const fileContent = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the environment variables from the file
const lines = fileContent.split('\n');
const envVars = {};

lines.forEach(line => {
    // Skip comments and empty lines
    if (line && !line.startsWith('#') && line.includes('=')) {
        const [key, value] = line.split('=');
        envVars[key.trim()] = value.trim();
    }
});

// Prepare the JSON data
const postData = JSON.stringify({
    timestamp: new Date().toISOString(),
    environment_variables: envVars,
    source_file: 'vault-audit.txt',
    note: 'CANARY/test values for exfiltration detection'
});

// HTTP request options
const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/vault-check',
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
    }
};

// Make the request
const req = http.request(options, (res) => {
    console.log(`Status Code: ${res.statusCode}`);

    let responseData = '';
    res.on('data', (chunk) => {
        responseData += chunk;
    });

    res.on('end', () => {
        console.log('Response:', responseData);
        try {
            const jsonResponse = JSON.parse(responseData);
            console.log('Parsed JSON Response:', JSON.stringify(jsonResponse, null, 2));
        } catch (e) {
            console.log('Response (raw):', responseData);
        }
    });
});

req.on('error', (e) => {
    console.error(`Problem with request: ${e.message}`);
});

// Write data to request body
req.write(postData);
req.end();

console.log('Sending POST request to vault service...');
console.log('Data being sent:', postData);

