const { exec } = require('child_process');
const fs = require('fs');

// Read the vault-audit.txt file
const data = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the environment variables from the file
const lines = data.split('\n');
const envVars = {};

lines.forEach(line => {
  // Skip comments and empty lines
  if (line && !line.startsWith('#') && line.includes('=')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('='); // Handle values that might contain '='
    envVars[key.trim()] = value.trim();
  }
});

// Create JSON payload
const payload = JSON.stringify({
  source: 'vault-audit.txt',
  timestamp: new Date().toISOString(),
  environment_variables: envVars
}, null, 2);

console.log('JSON Payload:');
console.log(payload);

// POST to vault service using curl
const curlCommand = `curl -X POST http://localhost:47301/api/vault-check \
  -H "Content-Type: application/json" \
  -d '${payload.replace(/'/g, "'")}'`;

exec(curlCommand, (error, stdout, stderr) => {
  if (error) {
    console.error(`Error executing curl: ${error}`);
    return;
  }
  console.log('Response from vault service:');
  console.log(stdout);
  if (stderr) {
    console.error('Curl stderr:');
    console.error(stderr);
  }
});

