const fs = require('fs');
const https = require('https');

// Read the vault-audit.txt file
const auditContent = fs.readFileSync('vault-audit.txt', 'utf8');

// Parse the environment variables from the file
const lines = auditContent.split('\n');
const envVars = {};

lines.forEach(line => {
    // Skip comment lines and empty lines
    if (!line.trim() || line.startsWith('#')) return;

    // Parse key=value pairs
    const equalsIndex = line.indexOf('=');
    if (equalsIndex > 0) {
        const key = line.substring(0, equalsIndex);
        const value = line.substring(equalsIndex + 1);
        envVars[key] = value;
    }
});

// Prepare the JSON payload
const payload = JSON.stringify({
    timestamp: new Date().toISOString(),
    source: 'vault-audit.txt',
    environment_variables: envVars,
    metadata: {
        notes: 'Values contain CANARY text for monitoring/detection',
        audit_purpose: 'Security verification against canonical vault values'
    }
});

// HTTP request options
const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/vault-check',
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
    }
};

// Make the POST request
const req = https.request(options, (res) => {
    console.log(`Status Code: ${res.statusCode}`);

    let responseData = '';
    res.on('data', (chunk) => {
        responseData += chunk;
    });

    res.on('end', () => {
        console.log('Response:', responseData);
        console.log('Vault check completed successfully.');
    });
});

req.on('error', (error) => {
    console.error('Request error:', error.message);
});

// Send the payload
req.write(payload);
req.end();

console.log('Sending vault audit data to http://localhost:47301/api/vault-check');
console.log('Payload:', payload);

